package glitch

import data.glitch_lib

# Define insecure protocol patterns
insecure_protocols = {"http", "ftp", "smtp", "telnet"}

# Define security attribute names to check
security_attributes = {
    "protocol", "enable_https", "use_https", "force_ssl", "enforce_https",
    "ssl_mode", "encryption_in_transit", "secure_transport",
    "enable_https_traffic_only", "secure_transfer", "allow_blob_public_access",
    "public_access", "require_ssl", "encryption", "listener_protocol",
    "redirect_http_to_https", "backend_protocol", "ssl_policy", "exposed_to_public",
    "port", "firewall_rules", "security_groups", "cdn_configuration",
    "environment_variables", "cloud_metadata", "user_data", "url", "endpoint",
    "uri", "base_url", "api_gateway"
}

# Check for insecure string values in attributes
check_insecure_string(attr) {
    attr.value.ir_type == "String"
    regex.match("(?i).*http://.*", attr.value.value)
} else {
    attr.value.ir_type == "String"
    insecure_protocols[attr.value.value]
} else {
    attr.value.ir_type == "String"
    attr.value.value == "disabled"
} else {
    attr.value.ir_type == "String"
    attr.value.value == "none"
}

# Check for insecure boolean values (false for security settings)
check_insecure_boolean(attr) {
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

# Main rule for detecting cleartext transmission
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    security_attributes[attr.name]

    # Check for insecure string or boolean values
    check_insecure_string(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information detected. Unencrypted protocol or insecure setting found. (CWE-319)"
    }
}

